describe('Accessibility Tests for Images', () => {
    beforeEach(() => {
        cy.visit('/'); // Replace with the actual URL of the application
    });

    it('should have descriptive alt text for all images', () => {
        cy.get('img').each(($img) => {
            const altText = $img.attr('alt');
            expect(altText).to.not.be.empty;
            expect(altText).to.not.equal('undefined');
        });
    });

    it('should not have images with empty alt text', () => {
        cy.get('img[alt=""]').should('have.length', 0);
    });
});
